INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0113', 0, 'adon', 'lord', 'Adon - lord or master as opposed to Adonai{H0136}, LordOfMine', 'אדון');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0136', 0, 'Adonai', 'LordOfMine', 'Only ever applied to God in the hebrew Bible it essentially means My Lord. An emphatic form of \'adon{H0113}\'.', 'אדני');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0347', 1, 'Job/Iyov', 'HatedOne', 'HatedOne. From the primitive root ayab{H0340}; to hate (as one of an opposite tribe or party); hence to be hostile - be an enemy', 'איוב');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0403', 0, 'aken', 'surely', 'Surely, truly, sometimes emphasising a contrast: however', 'אכן');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0410', 0, 'El', 'God', 'Singular God as opposed to the plural Elohim{H0430}', 'אל');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0426', 0, 'Elah', 'God', 'Elah - singular of Elohim{H0430} God or god', 'אלה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0430', 0, 'Elohim', 'God', 'Elohim - the plural of eloah, literally \'gods&apos; often used for the true and living God', 'אלהים');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0433', 0, 'Eloah', 'God', 'Eloah - the singular of elohim{H0430}, literally \'god\'.', 'אלה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0543', 0, 'amen', 'Absolutely', 'Amen! Absolutely! Most-certainly! Mark The Words. So be it. Emphatic YES! So let it be written, so let it be done. Truly. With all emphasis. Listen! If you get *one* thing... The Hebrew root amen also conveys meanings of firmness, reliability, and faithfulness.', 'אמן');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0776', 0, 'erets', 'ground', '\"earth\", land, ground. In Hebrew this word never means earth as in soil, but land, ground etc.', 'ארץ');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H0922', 0, 'vohu', 'waste', 'Usually translated void, the Hebrew really means waste, like a desert or wasteland.', 'בהו');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H1166', 0, 'baal', 'Marry/Own', 'Marry/Own', 'בעל');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H1167', 0, 'baal', 'Husband/Master/Owner', 'Husband/Master/Owner', 'בעל');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H1254', 0, 'bara', 'create-from-nothing', 'Hebrew speakers only use this word to mean a unique god-like act of creation as opposed to a casual \'I created a meal\'.', 'ברא');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H1376', 0, 'gevir', 'ruler', 'ruler, master. Not especially interesting perhaps in itself; were it not for the fact it is only used twice - in the story of Jacob as opposed to his brother, Esau - never of God or anyone else.', 'גביר');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H1814', 0, 'dalaq', 'hotly-pursue', 'Hotly-pursue, burn, ignite, inflame', 'דלק');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H2657', 1, 'Hepzibah', 'MyDelightIsInHer', 'Hepzibah = \"my delight is in her\" 1) the queen of King Hezekiah and mother of Manasseh 2) a name for Jesusalem (fig.)', 'חפצי־בה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H3050', 1, 'Yah', 'EverOne', 'Yah - An abbreviation of the proper name for God, Yahweh{H3068}', 'יה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H3068', 1, 'Yahweh', 'ForeverOne', 'Yud-Heh-Vav-Heh (Yahweh/Jehovah) - The proper name for God. In Jewish circles never spoken; normally spoken as Adonai{H0136} or HaShem', 'יהוה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H3444', 0, 'yeshua', 'help', 'deliverance, salvation, help', 'ישועה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H3742', 0, 'keruv', 'throne-angel', 'Cherubs are not cute baby angels but mighty angelic beings! The full meaning is unknown but my take, ThroneAngel is based on their presence with ForeverOne himself. Other suggestions are Blessers, Mighty Ones, Approachers, or Internal Ones.', 'כרוב');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H4756', 0, 'mare', 'lord', 'Master;lord. Only occurs in Daniel', 'מרא');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H4785', 1, 'Marah', 'BitterPlace', 'The word means Bitter, rather than BitterPlace but is used only for the spring with bitter water which was 3 days travel from the crossing place of the Red Sea in the peninsula of Sinai.', 'מרה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H4886', 0, 'mashach', 'anoint', 'to anoint (with oil)', 'משח');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H4899', 0, 'mashiach', 'anointed', 'anointed (Messiah)', 'משיח');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H5375', 0, 'nasa', 'carry', 'lift, carry, bear, hold, take', 'נשא');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H5542', 1, 'selah', 'SolidRock', 'The meaning of this word is unclear. It is used in psalms as some form of exclamation or perhaps a musical instruction. I have chosen SolidRock as a non-transliterative placeholder.', 'סלה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H5633', 0, 'ceren', 'Lord;tyrant', 'Lord/Tyrant', 'סרן');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H6212', 0, 'esev', 'plant', 'plant, vegetation', 'עשב');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H6635', 0, 'tsavah', 'armies', 'multitudes, hordes, hosts, armies. A crowd or large group of people, often soldiers. Used figuratively for a mass of things.', 'צבא');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H6757', 0, 'tsalmavet', 'death-shadow', 'From the Hebrew tsal (shadow) and mavet (death).', 'צלמות');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H7291', 0, 'radaph', 'pursue', 'Pursue, follow closely, chase', 'רדף');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H7307', 0, 'ruach', 'spirit/breath/breeze', 'ruach - wind, breath, spirit.', 'רוח');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H7706', 0, 'Shaddai', 'Almighty', 'Almighty - usually God almighty.', 'שדי');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H7723', 0, 'shav', 'emptily/unworthily', 'emptiness, vanity, falsehood 1a) emptiness, nothingness, vanity 1b) emptiness of speech, lying 1c) worthlessness (of conduct)', 'שוא');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H8064', 0, 'shamayim', 'sky', '\"heavens\", sky, skies. The Hebrew is plural and usually conveys the physical sky above our heads.', 'שמים');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H8314', 1, 'seraphim', 'BurningOnes', 'Fiery; Burning; burning ones', 'שרף');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H8392', 0, 'tevah', 'vessel', 'The ark - the vessel which Noah built; the basket vessel in which Moses was placed.', 'תבה');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('H8414', 0, 'TODO', 'TODO', 'TODO: used in the USFM text but missing from the imported SQL strongs table. Current visible forms: nothing x6; waste x4; vain x4; wild x2; confusion x2; vanity x2; things x1; wilderness x1; empty x1; space x1; meaningless x1.', 'תהו');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0005', 0, 'Abba', 'Daddy', 'Aramaic for father used to this day in Jewish circles as the most intimate word for father.', 'ἀββά');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0025', 0, 'agapeo', 'selflessly-love', 'Determined, active loving that has more to do with willing good for others than any emotional feeling. The verb of {G0026}', 'ἀγαπάω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0026', 0, 'agape', 'selfelss-love', 'The determined active love that has more to do with willing good for others than any emotional feeling. The noun of {G0025}', 'ἀγάπη');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0027', 0, 'agapetos', 'dear, dear-ones', 'Beloved, recipients of the greatest love{G0026}, loved.', 'ἀγαπητός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0264', 0, 'hamartano', 'fall-short', 'Falling short, miss, sin, shortcoming.', 'ἁμαρτάνω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0265', 0, 'hamartema', 'shortcoming', 'Falling short, miss, sin, shortcoming.', 'ἁμάρτημα');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0266', 0, 'hamartia', 'shortcomings', 'Falling short, miss, sin, shortcomings.', 'ἁμαρτία');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0268', 0, 'hamartolos', 'shortcomer', 'One who falls short, misses, a sinner, shortcomer.', 'ἁμαρτωλός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0281', 0, 'amen', 'Absolutely', 'Amen! Absolutely! Most-certainly! Mark The Words. So be it. Emphatic YES! So let it be written, so let it be done. Truly. With all emphasis. Listen! If you get *one* thing... The Hebrew root amen also conveys meanings of firmness, reliability, and faithfulness.', 'ἀμήν');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0435', 0, 'aner', 'man', 'An adult male human.', 'ἀνήρ');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0444', 0, 'anthropos', 'people', 'Often translated \'men\' but is not gender specific - so humans, people, humankind.', 'ἄνθρωπος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0500', 0, 'antikristos', 'anti-AnointedOne', 'Christ and Messiah both mean Anointed One. An opposer of AnointedOne. Antichrist.', 'ἀντίχριστος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0652', 0, 'apostolos', 'ambassador', 'Apostle is merely a transliteration of the Greek, which means \'sent out one\', \'set apart one\'. I believe ambassador is the most meaningful modern English equivalent.', 'ἀπόστολος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G0862', 0, 'afthartos', 'permanent', 'Un-temporary; imperishable; immortal; permanent', 'ἄφθαρτος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G1203', 0, 'Despotes', 'Master', 'Master - the English \'despot\' comes from this word.', 'δεσπότης');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G1378', 0, 'dogma', 'ordinance/decree', 'One of 3 main words for law/instruction in the New Testament, dogma, entole and nomos. This one is where the English \'dogmatic\' comes from.', 'δόγμα');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G1393', 1, 'Dorcas', 'Gazelle', 'Dorcas is the Greek translation of the Aramaic Tabitha, which means gazelle in both languages. In the New Testament, Tabitha (or Dorcas) is a woman known for her good works and acts of charity in Joppa.', 'Δορκάς');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G1459', 0, 'Enkataleipo', 'Abandon', 'Abandon or Forsake', 'ἐγκαταλείπω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G1672', 0, 'Hellen', 'Greek', 'The Greeks: The ancient Greeks referred to themselves as the Hellenes. May also refer to Gentiles in the New Testament.', 'Ἕλλην');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G1785', 0, 'entole', 'commandment', 'One of 3 main words for law/instruction in the New Testament, dogma, entole and nomos.', 'ἐντολή');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2097', 0, 'euangelizo', 'proclaim-good-news', 'This is the word we get evangelize from. It is derived from eu (good) and angelos{G0032} (messenger) and it means proclaim-good-news', 'εὐαγγελίζομαι');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2098', 0, 'euangelion', 'good-news', 'From which we get the English \'evangelise\'. Gospel, though etymologically accurate (\'good spiel\'), is colloquially more closely associated with \'truth\' than \'good news\'.', 'εὐαγγέλιον');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2127', 0, 'eulogeo', 'praise', 'From which we get the English \'eulogise\'. Often translated bless, it really means praise.', 'εὐλογέω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2128', 0, 'eulogetos', 'praiseworthy', 'Often translated blessed, it really means praiseworthy.', 'εὐλογητός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2129', 0, 'eulogia', 'praise', 'From which we get the English \'eulogy\'. Often translated blessing, it really means praise.', 'εὐλογία');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2209', 0, 'zemia', 'damage', '\'damage/loss&apos; loss, damage', 'ζημία');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2296', 0, 'thaumazo', 'stunned', 'To be stunned, to wonder, be (utterly) amazed, marvel, to wonder at, wonder greatly.', 'θαυμάζω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2315', 0, 'Theopneustos', 'Godbreathed', 'Literally the breath/wind/spirit-making of God. God breathed as one word. Only occurs once in 2 Timothy 3:16', 'θεόπνευστος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2316', 0, 'Theos', 'God', 'Very similar in usage to the English, in that the word may refer to the true and living God or pretend gods.', 'θεός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2321', 1, 'Theophilos', 'FriendOfGod', 'The name Theophilos is a contraction of Theos{G2316} and philos{G5384}.', 'Θεόφιλος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2364', 0, 'thugater', 'daughter', 'Daughter, and by extension a term of endearment, usually towards younger women', 'θυγάτηρ');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2519', 0, 'kathegetes', 'teacher', 'teacher', 'καθηγητής');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2634', 0, 'katakurieuo', 'master', 'master - \'against-lord\'', 'κατακυριεύω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2635', 0, 'katalaleo', 'slander', 'Literally \'against-speak\'. To slander, to speak against, to incriminate.', 'καταλαλέω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2823', 0, 'klibanos', 'fire-oven', 'This was an earthenware pot for baking bread. It was broader at the bottom than at the top, and with a fire lit inside, the dough was baked by being spread on the outside.', 'κλίβανος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2960', 0, 'Kuriakos', 'Master', 'Pertaining to the Lord', 'κυριακός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2961', 0, 'kurieuo', 'dominate', 'master, lord, dominate', 'κυριεύω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G2962', 0, 'Kurios', 'Lord', 'Lord. Notably this may stand for Yahweh{H3068} as the Jewish tradition to never say Yahweh{H3068}, and say Adonai{H0136} (Lord) instead, was in place long before the New Testament (about 300 BC)', 'κύριος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3106', 0, 'makarizo', 'happy', 'Often translated Blessed, a bit old fashioned now, it is an emphatic form of happy.', 'μακαρίζω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3107', 0, 'makarios', 'happier', 'Often translated Blessed, a bit old fashioned now, it is an emphatic form of happy.', 'μακάριος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3126', 0, 'mammon', 'your-savings', 'TrustTreasure - what you rely on, your-savings, investment.', 'μαμμωνᾶς');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3323', 0, 'Messias', 'Messiah', 'Greek transliteration of the Hebrew {H4899}, Mashiach, Messiah. Anointed; Messiah (in Jewish tradition not THE messiah). Only found in John 1 and 4. Equivalent to {G5547}', 'Μεσσίας');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3339', 0, 'metamorfoo', 'transformed', 'This is the Greek root word from which we get the English word Metamorphose.', 'μεταμορφόω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3551', 0, 'nomos', 'law', 'One of 3 main words for law/instruction in the New Testament, dogma, entole and nomos. This one is frequently used for Torah, Mosaic Law.', 'νόμος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3759', 0, 'ouai', 'aah', 'An exclamation of grief. Wail! Nooo! woe! aah! alas!', 'οὐαί');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3841', 0, 'Pantokrator', 'Almighty', 'Almighty - only applied (obviously!) to God. Equivalent to {H7706}.', 'παντοκράτωρ');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3870', 0, 'parakaleo', 'strongly-encourage', 'This Greek word comes from para (from, by, beside, near, with) and kaleo (to call, to invite, to name) strong-encouraging, comforting, exhorting, urging.', 'παρακαλέω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3874', 0, 'paraklesis', 'strong-encouragement', 'This Greek word comes from para (from, by, beside, near, with) and kaleo (to call, to invite, to name) strong-encouragement, comfort, exhortation, urging.', 'παράκλησις');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3875', 0, 'parakletos', 'strong-encourager', 'This Greek word comes from para (from, by, beside, near, with) and kaleo (to call, to invite, to name) strong-encourager, comforter, exhorter, urging-one. Interestingly, John is the only New Testament author to use this word.', 'παράκλητος');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3985', 0, 'peirazo', 'temptation', 'Most often translated temptation. Testing, trial, trap.', 'πειράζω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G3986', 0, 'peirasmos', 'testing', 'Often translated temptation. Testing, trial, trap.', 'πειρασμός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G4100', 0, 'pisteuo', 'trust', 'Often translated faith, but it&apos;s trusting a person, not just faith in an idea.', 'πιστεύω');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G4102', 0, 'pistis', 'trust', 'Often translated faith, but it&apos;s trusting a person, not just faith in an idea.', 'πίστις');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G4550', 0, 'sapros', 'rotten', 'This has a strongly negative meaning — not just rotten but corrupting or causing disease or being diseased.', 'σαπρός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G4657', 0, 'skubalon', 'filth', 'Disgusting rubbish; rotten; filth; refuse; dung. This can refer to any of a number of rotten, decaying things that must be disposed of. It is only used in Philippians 3:8.', 'σκύβαλον');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G4995', 0, 'sofronismos', 'soundness-of-mind', 'This is subtle and can mean soundness-of-mind, self-discipline, prudence, wisdom. It is only used in 2 timothy 1:7.', 'σωφρονισμός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G5207', 0, 'huios', 'son', '\"The Son of Man\" is an OT phrase usually meaning \"human being\", that in the NT is used almost exclusively as a title referring to AnointedOne.', 'υἱός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G5349', 0, 'fthartos', 'temporary', 'Temporary or mortal; not lasting, perishable, impermanent.', 'φθαρτός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G5502', 0, 'cheroubim', 'throne-angel', 'Transliteration of Hebrew kerub{H3742}. Cherubs are not cute baby angels but mighty angelic beings! The full meaning is unknown but my take, throne-angel is based on their presence with ForeverOne himself. Other suggestions are Blessers, Mighty Ones, Approachers, or Internal Ones.', 'χερουβίμ');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G5509', 0, 'chiton', 'tunic', 'Strictly a tunic but often the main or only garment worn, either by men or women. Robe; clothing; undergarment.', 'χιτών');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G5546', 0, 'kristianos', 'christian', 'Christian; \'one belonging to Christ\'; Messianic believer;', 'Χριστιανός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G5547', 0, 'Kristos', 'AnointedOne', 'Christ and Messiah both mean Anointed One', 'Χριστός');
INSERT INTO strongs (strongsNumber, strongsIsName, strongsOriginal, strongsEnglish, strongsDefinition, strongsOriginalScript) VALUES('G5580', 0, 'pseudokristos', 'false-AnointedOnes', 'Christ and Messiah both mean Anointed One. Ungodly imitators of Jesus Christ will come who make bold claims but are not Him.', 'ψευδόχριστος');
